const hash = 'a'.repeat(64), metadata = { model: 'synthetic', promptVersion: 'foxy-chat-v1', schemaVersion: 'foxy-answer-v1' };
const config = { maxConcurrency: 1, deadlineMs: 30000, maxJobAgeMs: 300000, dailyActorRequests: 5, dailyGlobalRequests: 20,
  maxOutputTokens: 100, inputUsdPerMillion: 2, outputUsdPerMillion: 3, dailyBudgetUsd: 1 };
const answer = { schemaVersion: 'foxy-answer-v1', title: 'Respuesta', markdown: 'Contenido docente', references: [], warnings: [], missingInformation: [] };
const ready = (changes = {}) => ({ state: 'READY', answer, referenceMap: [], sourceReport: [], usage: { inputTokens: 10, outputTokens: 20 }, ...changes });
async function ledger(query, owner) {
  return query("SELECT scope,request_count,reserved_microusd::text AS reserved,consumed_microusd::text AS consumed FROM ai_usage_daily WHERE scope IN ('global',$1) AND capability='study-plan-v1' ORDER BY scope", owner);
}
function host(query, owner) {
  return { run: async (_request, _write, fn) => fn({ query }, { id: owner, account_role: 'teacher' }),
    classroom: async (_tx, actor, id) => {
      const [room] = await query('SELECT * FROM classrooms WHERE id=$1::uuid', id);
      if (!room || room.teacher_id !== actor.id) throw Object.assign(new Error('FORBIDDEN'), { code: 'FORBIDDEN' }); return room;
    } };
}
async function setup(api, query, f, classroom = false) {
  const tx = { query }, conversations = api.createFoxyConversationRepository(), turns = api.createFoxyTurnRepository();
  const context = classroom ? { kind: 'CLASSROOM', classroomId: f.rooms.teach.id } : { kind: 'GENERAL' };
  const { conversation } = await conversations.create(tx, f.teacherActor, { requestId: randomUUID(), title: 'Cierre', context }, hash);
  const selection = { topicIds: classroom ? [f.rooms.teach.topic] : [], sourceIds: [] };
  const snapshot = await new api.FoxyGroundingSnapshotService(host(query, f.teacherActor), conversations).capture({}, conversation.id, selection);
  const { turn } = await turns.enqueue(tx, f.teacherActor, conversation.id,
    { requestId: randomUUID(), revision: '0', purpose: 'CHAT', text: 'Consulta', selection }, snapshot, hash, metadata);
  const database = { $transaction: fn => fn({ $queryRawUnsafe: query }) }, queue = api.createFoxyTurnQueue({ database, configuration: config });
  const lease = await queue.claim(); assert.equal(lease.turnId, turn.id);
  const budget = api.createFoxyTextBudget({ configuration: config });
  const completion = api.createFoxyTurnCompletion({ database, budget, configuration: { maxJobAgeMs: config.maxJobAgeMs } });
  return { tx, queue, lease, budget, completion, turn, conversation };
}
async function state(query, turnId) {
  const [row] = await query(`SELECT state,error_code,answer,reference_map,source_report,lease_nonce,lease_until,
    dispatch_count,reserved_microusd::text AS reserved FROM foxy_turns WHERE id=$1::uuid`, turnId);
  return row;
}

